# -*- coding=utf-8 -*-

class Personne:

    # Konstruktor
    def __init__(self,prenom,nom,age):
        self.prenom=prenom;
        self.nom=nom;
        self.age=age;

    # Methode
    def identite(self):
        # verwendet a priori nicht vorhandene Attribute
        return "[{0},{1},{2}]".format(self.prenom,self.nom,self.age)

# ---------------------------------- main
# ein Objekt vom Typ „Person“
p=Personne("Paul","Langevin",48)
# Aufruf einer Methode
print "personne={0}\n".format(p.identite())
</code></pre> <p>Anmerkungen:</p> <ul> <li>Zeile 6: Der Konstruktor einer Klasse heißt __init__. Wie bei den anderen Methoden ist sein erster Parameter „self“;</li> <li>Zeile 18: Ein Objekt Personne wird mit dem Konstruktor der Klasse erstellt.</li> </ul> Ergebnisse <pre><code>personne=[Paul,Langevin,48]
</code></pre> <p></p>

