# -*- coding=utf-8 -*-

import re

# -------------------
# eine benutzerdefinierte Ausnahmeklasse
class MyError(Exception):
    pass

class Personne:

    # Konstruktor
    def __init__(self,prenom="x",nom="x",age=0):
         # Der Vorname darf nicht leer sein
        match=re.match(r"^\s*(\S+)\s*$",prenom)
        if not match:
            raise MyError("Le prenom ne peut etre vide")
        else:
            self.prenom=match.groups()[0]
        # Der Nachname darf nicht leer sein
        match=re.match(r"^\s*(\S+)\s*$",nom)
        if not match:
            raise MyError("Le nom ne peut etre vide")
        else:
            self.nom=match.groups()[0]
        # Das Alter muss gültig sein
        match=re.match(r"^\s*(\d+)\s*$",str(age))
        if not match:
            raise MyError("l'age doit etre un entier positif")
        else:
            self.age=match.groups()[0]

    def __str__(self):
        return "[{0},{1},{2}]".format(self.prenom,self.nom,self.age)

# ---------------------------------- Hand
# ein Objekt vom Typ „Person“
try:
    p=Personne("  Paul  ","  Langevin  ",48)
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
# ein weiteres Objekt „Person“
try:
    p=Personne("  xx  ","  yy  ","  zz")
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
# eine weitere Person
try:
    p=Personne()
    print "personne={0}".format(p)
except MyError, erreur:
    print erreur
</code></pre> <p>Anmerkungen:</p> <ul> <li>Zeilen 7–8: Eine Klasse MyError, die von der Klasse Exception abgeleitet ist. Sie fügt dieser keine neuen Funktionen hinzu. Sie dient lediglich dazu, eine benutzerdefinierte Ausnahme zu definieren;</li> <li>Zeile 13: Der Konstruktor verfügt über Standardwerte für seine Parameter. Somit entspricht die Operation p=Personne() der Formel p=Personne("x","x",0);</li> <li>Zeilen 15–9: Der Parameter prenom wird analysiert. Er darf nicht leer sein. Ist dies nicht der Fall, wird die Ausnahme MyError mit einer Fehlermeldung ausgelöst;</li> <li>Zeilen 21–25: Gleiches gilt für den Namen;</li> <li>Zeilen 27–31: Überprüfung des Alters;</li> <li>Zeilen 33–34: Die Funktion __str__ ersetzt die Methode, die zuvor identite hieß;</li> <li>Zeilen 38–42: Instanziierung einer Person und anschließende Anzeige ihrer Identität;</li> <li>Zeile 39: Instanziierung;</li> <li>Zeile 40: Anzeige. Der Vorgang fordert an, die Person p in Form einer Zeichenkette anzuzeigen. Der Python-Interpreter ruft dann automatisch die Methode p.__str__() auf, sofern diese existiert. Diese Methode erfüllt dieselbe Funktion wie die Methode toString() in Java oder in den Sprachen .NET;</li> <li>Zeilen 41–42: Behandlung einer möglichen Ausnahme vom Typ MyError. Zeigt dann die mit der Ausnahme verbundene Fehlermeldung an;</li> <li>Zeilen 44–48: Gleiches gilt für eine zweite Person, die mit falschen Parametern instanziiert wurde;</li> <li>Zeilen 50–54: Gleiches gilt für eine dritte Instanz, die mit den Standardparametern instanziiert wurde.</li> </ul> Ergebnisse <pre><code>personne=[Paul,Langevin,48]
l'age doit etre un entier positif
personne=[x,x,0]
</code></pre> <p></p>

