# -*- coding=utf-8 -*-

import re

# -------------------
# eine eigene Ausnahmeklasse
class MyError(Exception):
    pass

class Personne:
    # Attribute der Klasse
    # nicht deklariert – können dynamisch erstellt werden

    # Konstruktor
    def __init__(self,prenom="x",nom="x",age=0):
         # Der Vorname darf nicht leer sein
        match=re.match(r"^\s*(\S+)\s*$",prenom)
        if not match:
            raise MyError("Le prenom ne peut etre vide")
        else:
            self.prenom=match.groups()[0]
        # Der Nachname darf nicht leer sein
        match=re.match(r"^\s*(\S+)\s*$",nom)
        if not match:
            raise MyError("Le nom ne peut etre vide")
        else:
            self.nom=match.groups()[0]
            # Das Alter muss gültig sein
        match=re.match(r"^\s*(\d+)\s*$",str(age))
        if not match:
            raise MyError("l'age doit etre un entier positif")
        else:
            self.age=match.groups()[0]

    def initWithPersonne(self,p):
        # initialisiert das aktuelle Objekt mit einer Person p
        self.__init__(p.prenom,p.nom,p.age)

    def __str__(self):
        return "[{0},{1},{2}]".format(self.prenom,self.nom,self.age)

# ---------------------------------- main
# ein Objekt vom Typ „Person“
try:
    p0=Personne("  Paul  ","  Langevin  ",48)
    print "personne={0}".format(p0)
except MyError, erreur:
    print erreur
# ein weiteres Objekt „Person“
try:
    p1=Personne("  xx  ","  yy  ","  zz")
    print "personne={0}".format(p1)
except MyError, erreur:
    print erreur
# eine weitere Person
p2=Personne()
try:
    p2.initWithPersonne(p0)
    print "personne={0}".format(p2)
except MyError, erreur:
    print erreur

</code></pre> <p>Anmerkungen:</p> <ul> <li>Der Unterschied zum vorherigen Skript liegt in den Zeilen 35–37. Die Methode initWithPersonne wurde hinzugefügt. Diese ruft den Konstruktor __init__ auf. Es gibt keine Möglichkeit, wie in typisierten Sprachen Methoden mit demselben Namen zu haben, die sich durch die Art ihrer Parameter oder ihres Ergebnisses unterscheiden. Es ist daher nicht möglich, mehrere Konstruktoren zu haben, die das Objekt anhand unterschiedlicher Parameter erstellen würden, in diesem Fall ein Objekt vom Typ Personne.</li> </ul> Ergebnisse <pre><code>personne=[Paul,Langevin,48]
l'age doit etre un entier positif
personne=[Paul,Langevin,48]
</code></pre> <p></p>

Programm (classes_07) <pre><code>
# -*- coding=utf-8 -*-

import re

class Personne:
    ...

class Enseignant(Personne):
    def __init__(self,prenom="x",nom="x",age=0,discipline="x"):
        Personne.__init__(self,prenom,nom,age)
        self.discipline=discipline

    def __str__(self):
        return "[{0},{1},{2},{3}]".format(self.prenom,self.nom,self.age,self.discipline)


# ---------------------------------- Hand
# Erstellung einer Liste von Personenobjekten und abgeleiteten Objekten
groupe=[Enseignant("Paul","Langevin",48,"anglais"), Personne("Sylvie","Lefur",70)]
# Identität dieser Personen
for i in range(len(groupe)):
  print "groupe[{0}]={1}".format(i,groupe[i])

</code></pre> <p>Anmerkungen:</p> <ul> <li>Zeilen 5–6: Die bereits definierte Klasse „Personne“;</li> <li>Zeile 8: Deklariert die Klasse „Enseignant“ als abgeleitete Klasse der Klasse „Person“;</li> <li>Zeile 10: Der Konstruktor der abgeleiteten Klasse Enseignant muss den Konstruktor der übergeordneten Klasse Personne aufrufen;</li> <li>Zeilen 21–22: Um „groupe[i]“ anzuzeigen, verwendet der Interpreter die Methode „groupe[i].__str__()“. Die verwendete Methode __str__() ist die der tatsächlichen Klasse „groupe[i]“, wie  die folgenden Ergebnisse zeigen.</li> </ul> Ergebnisse <pre><code>groupe[0]=[Paul,Langevin,48,anglais]
groupe[1]=[Sylvie,Lefur,70]
</code></pre> <p></p>

